return {
  service: 'health-check',
  timestamp: new Date().toISOString(),
  components: []
};

// Aggregate health check results
const items = $input.all();

const components = {
  redis: {
    status: 'unknown',
    message: 'Not checked',
    responseTime: null
  },
  bms_api: {
    status: 'unknown',
    message: 'Not checked',
    responseTime: null
  },
  ollama: {
    status: 'unknown',
    message: 'Not checked',
    responseTime: null
  }
};

// Process Redis check
const redisItem = items.find(item => item.json.service === 'redis' || item.json.reply === 'PONG');
if (redisItem) {
  if (redisItem.json.reply === 'PONG' || redisItem.json === 'PONG') {
    components.redis.status = 'healthy';
    components.redis.message = 'Redis is responsive';
  } else {
    components.redis.status = 'unhealthy';
    components.redis.message = redisItem.json.error || 'Redis ping failed';
  }
}

// Process BMS API check
const bmsItem = items.find(item => item.json.status || item.json.version);
if (bmsItem) {
  if (bmsItem.json.status === 'healthy') {
    components.bms_api.status = 'healthy';
    components.bms_api.message = `BMS API v${bmsItem.json.version || '1.0.0'}`;
  } else {
    components.bms_api.status = 'unhealthy';
    components.bms_api.message = bmsItem.json.error || 'BMS API unreachable';
  }
}

// Process Ollama check
const ollamaItem = items.find(item => item.json.models || item.json.error);
if (ollamaItem) {
  if (ollamaItem.json.models) {
    components.ollama.status = 'healthy';
    components.ollama.message = `Ollama running with ${ollamaItem.json.models.length} models`;
  } else {
    components.ollama.status = 'unhealthy';
    components.ollama.message = ollamaItem.json.error || 'Ollama unreachable';
  }
}

// Determine overall health
const allHealthy = Object.values(components).every(c => c.status === 'healthy');
const anyUnhealthy = Object.values(components).some(c => c.status === 'unhealthy');

let overallStatus = 'unknown';
if (allHealthy) {
  overallStatus = 'healthy';
} else if (anyUnhealthy) {
  overallStatus = 'degraded';
} else {
  overallStatus = 'unknown';
}

return {
  status: overallStatus,
  timestamp: new Date().toISOString(),
  components: components,
  version: '1.0.0',
  environment: 'POC'
};
